package project.init.framework.error;import lombok.Getter;import lombok.Setter;import project.init.framework.utils.DateTimeUtils;import java.time.Instant;@Getter@Setterpublic class ApiError extends BaseResponse {    private String path;    private Instant timestamp = DateTimeUtils.getCurrentTimeUTC();    public ApiError(int code, Object message, String path) {        super(code, message);        this.path = path;    }}